////////////////////////////////////////////////////////////////////////////////
// IVLAB 239 Ti60F225 initial top
// HyperRAM mode is selected by exactly one of:
//   `HYPERRAM_HR1   single-chip controller on HyperRAM1 pins
//   `HYPERRAM_HR2   single-chip controller on HyperRAM2 pins
//   `HYPERRAM_DUAL  dual-chip controller on both HyperRAM1 and HyperRAM2
// src/build.vh is generated by ./run.sh / scripts/select_hyperram.sh
////////////////////////////////////////////////////////////////////////////////
`define EFX_IPM
//`define ENABLE_VIO_DEBUG

`timescale 1ns / 1ps

`include "src/build.vh"
// RISC-V remains a generated IP include; project-owned functional modules are
// separate Efinity design sources rather than being hidden inside top.v.  A
// source-level checker may define TOP_EXTERNAL_RISCV because the generated IP
// contains encrypted simulator-specific models which Icarus cannot parse.
`ifndef TOP_EXTERNAL_RISCV
//`include "ip/riscv/riscv.v"
`endif

`ifndef HYPERRAM_HR1
`ifndef HYPERRAM_HR2
`ifndef HYPERRAM_DUAL
`define HYPERRAM_DUAL
`endif
`endif
`endif

`ifdef HYPERRAM_DUAL
`include "dual_hyperram_ctrl_define.svh"
`else
`include "hyperram_ctrl_define.svh"
`endif

module top #(
  parameter AWR_LEN = 63,
  parameter TOP_DBW = 16
) (
// `ifdef ENABLE_VIO_DEBUG
//   // USER1 is reserved for the Efinity VIO/LA debugger.
//   input  wire                 jtag_inst2_DRCK,
//   input  wire                 jtag_inst2_RESET,
//   input  wire                 jtag_inst2_TMS,
//   input  wire                 jtag_inst2_RUNTEST,
//   input  wire                 jtag_inst2_SEL,
//   input  wire                 jtag_inst2_SHIFT,
//   input  wire                 jtag_inst2_TDI,
//   input  wire                 jtag_inst2_CAPTURE,
//   input  wire                 jtag_inst2_TCK,
//   input  wire                 jtag_inst2_UPDATE,
//   output wire                 jtag_inst2_TDO,
// `endif
  // USER2 is always connected to the Sapphire RISC-V debug transport.  It is
  // retained in release builds as well, matching the reference ISP project;
  // only the USER1 VIO/LA core is controlled by ENABLE_VIO_DEBUG.

  input  wire                 jtag_inst1_DRCK,
  input  wire                 jtag_inst1_RESET,
  input  wire                 jtag_inst1_TMS,
  input  wire                 jtag_inst1_RUNTEST,
  input  wire                 jtag_inst1_SEL,
  input  wire                 jtag_inst1_SHIFT,
  input  wire                 jtag_inst1_TDI,
  input  wire                 jtag_inst1_CAPTURE,
  input  wire                 jtag_inst1_TCK,
  input  wire                 jtag_inst1_UPDATE,
  output wire                 jtag_inst1_TDO,

  // Oscillator
  input  wire                 intosc_clkout,
  output wire                 intosc_en,
  // Clock / PLL
  input  wire                 clk50M,
  input  wire                 clk,

  input  wire                 hbram_ref,

  input  wire                 hbramClk,
  input  wire                 hbramClk_cal,
`ifdef HYPERRAM_DUAL
  input  wire                 hbramClk_cal_2,
`endif
  input  wire                 hbramClk_pll_locked,
  output wire                 hbramClk_pll_rstn,
  output wire                 sysClk_pll_rstn,
  // UART for debug
  input  wire                 UART_FPGA_TX,
  input  wire                 UART_ST_FR,
  output wire                 UART_FPGA_RX,
  output wire                 UART_SR_FT,
  // Debug UART direct to SoC (controlled by DEBUG_UART_DIRECT_CONNECT macro)
  input  wire                 DEBUG_UART_RX,
  output wire                 DEBUG_UART_TX,
  // ADV7391 control and 27 MHz BT.656 pixel clocks generated by my_sys PLL.
  input  wire                 adv_ctrl_clk,
  input  wire                 clk_da,
  // BT.1120 input (LGCS123, 1280x1024 @ 30 Hz)
  input  wire                 bt1120_clk,
  input  wire [         15:0] bt1120_data,
  // PLL_TL0 outputs: clk_dvp=100 MHz for the proven DVP interface and an
  // independent clk_scaler=160 MHz for video scaling.
  // dvp_pclk is driven straight from this PLL via a clkout pad in the
  // peripheral interface, so it is not an RTL port here.
  input  wire                 clk_dvp,
  input  wire                 clk_scaler,
  input  wire                 pll_bt1120_locked,
  // 8-bit DVP output. HS pad carries dvp_valid (receiver convention).
  output wire                 dvp_vs,
  output wire                 dvp_hs,
  output wire [          7:0] dvp_data,
  // ADV7391 digital video, reset and I2C interface.
  output wire                 DA_HS,
  output wire [          7:0] DA_P,
  output wire                 DA_RST,
  input  wire                 DA_SCL_IN,
  output wire                 DA_SCL_OUT,
  output wire                 DA_SCL_OE,
  input  wire                 DA_SDA_IN,
  output wire                 DA_SDA_OUT,
  output wire                 DA_SDA_OE,
  output wire                 DA_VS,
  // Configuration Flash user-mode interface.  The Sapphire boot ROM uses
  // SPI0 to load the application image stored at Flash offset 0x00400000.
  output wire                 CFG_nCSO,
  output wire                 CFG_DCLK,
  input  wire                 CFG_D0_IN,
  output wire                 CFG_D0_OUT,
  output wire                 CFG_D0_OE,
  input  wire                 CFG_D1_IN,
  output wire                 CFG_D1_OUT,
  output wire                 CFG_D1_OE,
  input  wire                 CFG_D2_IN,
  output wire                 CFG_D2_OUT,
  output wire                 CFG_D2_OE,
  input  wire                 CFG_D3_IN,
  output wire                 CFG_D3_OUT,
  output wire                 CFG_D3_OE,
  // PLL phase shift
  output wire [          2:0] hbc_cal_SHIFT,
  output wire [          4:0] hbc_cal_SHIFT_SEL,
  output wire                 hbc_cal_SHIFT_ENA,
  // HyperRAM chip 1 (HR1 / DUAL) or remapped chip 2 (HR2 peri)
  output wire                 hbc_rst_n,
  output wire                 hbc_cs_n,
  output wire                 hbc_ck_p_HI,
  output wire                 hbc_ck_p_LO,
  output wire                 hbc_ck_n_HI,
  output wire                 hbc_ck_n_LO,
  output wire [TOP_DBW/8-1:0] hbc_rwds_OUT_HI,
  output wire [TOP_DBW/8-1:0] hbc_rwds_OUT_LO,
  input  wire [TOP_DBW/8-1:0] hbc_rwds_IN_HI,
  input  wire [TOP_DBW/8-1:0] hbc_rwds_IN_LO,
  input  wire [  TOP_DBW-1:0] hbc_dq_IN_LO,
  input  wire [  TOP_DBW-1:0] hbc_dq_IN_HI,
  output wire [TOP_DBW/8-1:0] hbc_rwds_OE,
  output wire [  TOP_DBW-1:0] hbc_dq_OUT_HI,
  output wire [  TOP_DBW-1:0] hbc_dq_OUT_LO,
  output wire [  TOP_DBW-1:0] hbc_dq_OE
`ifdef HYPERRAM_DUAL
  ,
  // HyperRAM chip 2
  output wire                 hbc_rst_n_2,
  output wire                 hbc_cs_n_2,
  output wire                 hbc_ck_p_2_HI,
  output wire                 hbc_ck_p_2_LO,
  output wire                 hbc_ck_n_2_HI,
  output wire                 hbc_ck_n_2_LO,
  output wire [TOP_DBW/8-1:0] hbc_rwds_2_OUT_HI,
  output wire [TOP_DBW/8-1:0] hbc_rwds_2_OUT_LO,
  input  wire [TOP_DBW/8-1:0] hbc_rwds_2_IN_HI,
  input  wire [TOP_DBW/8-1:0] hbc_rwds_2_IN_LO,
  input  wire [  TOP_DBW-1:0] hbc_dq_2_IN_LO,
  input  wire [  TOP_DBW-1:0] hbc_dq_2_IN_HI,
  output wire [TOP_DBW/8-1:0] hbc_rwds_2_OE,
  output wire [  TOP_DBW-1:0] hbc_dq_2_OUT_HI,
  output wire [  TOP_DBW-1:0] hbc_dq_2_OUT_LO,
  output wire [  TOP_DBW-1:0] hbc_dq_2_OE
`else
  ,
  // Single-chip demo status LEDs / peri GPIOs
  output wire                 test_good,
  output wire                 test_fail,
  output wire                 hbc_cal_pass
`endif
);

