  // Sapphire soft-core bring-up signals.  Its HyperRAM data master and axiA
  // peripheral master are independent; axiA terminates in the control fabric
  // while the high-bandwidth master shares the live memory bus.  VIO selects
  // whether the X2000 return path remains the proven UART bypass (0) or is
  // driven by the soft-core UART (1).
  // CPU AXI access and UART reply ownership are deliberately independent.
  // Keeping both low preserves the proven video and machine-UART bypass.
  // Release builds contain no VIO-controlled functional path. Debug builds
  // retain VIO, with s14 selecting the same release defaults or manual mode.
  wire               uart_softcore_enable;
  wire               riscv_uart_reply_enable;
  wire               riscv_soft_reset_vio;
  wire               riscv_uart_monitor_x2000;
  wire               riscv_diag_clear;
// `ifdef ENABLE_VIO_DEBUG
//   wire               uart_softcore_enable_vio; // VIO s6
//   wire               riscv_uart_reply_enable_vio; // VIO s13
//   wire               riscv_manual_mode_vio; // VIO s14: 0=auto, 1=manual
//   wire               riscv_soft_reset_vio_raw; // VIO s10
//   wire               riscv_uart_monitor_x2000_vio; // VIO s11
//   wire               riscv_diag_clear_vio; // VIO s12
//   assign uart_softcore_enable      = riscv_manual_mode_vio ? uart_softcore_enable_vio      : 1'b1;
//   assign riscv_uart_reply_enable   = riscv_manual_mode_vio ? riscv_uart_reply_enable_vio   : 1'b1;
//   assign riscv_uart_monitor_x2000  = riscv_manual_mode_vio ? riscv_uart_monitor_x2000_vio  : 1'b1;
//   assign override                  = riscv_manual_mode_vio ? override_vio                  : 1'b0;
//   assign dyn_pll_phase_en          = riscv_manual_mode_vio ? dyn_pll_phase_en_vio          : 1'b0;
//   assign dyn_pll_phase_sel         = riscv_manual_mode_vio ? dyn_pll_phase_sel_vio         : 3'b000;
//   assign mask_enable_vio           = riscv_manual_mode_vio ? mask_enable_vio_raw           : 1'b0;
//   assign mask_buffer_select_vio    = riscv_manual_mode_vio ? mask_buffer_select_vio_raw    : 1'b0;
//   assign rtl_mask_mode             = riscv_manual_mode_vio ? rtl_mask_mode_vio             : 1'b0;
//   assign riscv_soft_reset_vio      = riscv_manual_mode_vio ? riscv_soft_reset_vio_raw      : 1'b0;
//   assign riscv_diag_clear          = riscv_manual_mode_vio ? riscv_diag_clear_vio          : 1'b0;
// `else
  assign uart_softcore_enable      = 1'b1;
  assign riscv_uart_reply_enable   = 1'b1;
  assign riscv_uart_monitor_x2000  = 1'b1;
  assign override                  = 1'b0;
  assign dyn_pll_phase_en          = 1'b0;
  assign dyn_pll_phase_sel         = 3'b000;
  assign mask_enable_vio           = 1'b0;
  assign mask_buffer_select_vio    = 1'b0;
  assign rtl_mask_mode             = 1'b0;
  assign riscv_soft_reset_vio      = 1'b0;
  assign riscv_diag_clear          = 1'b0;
// `endif
  wire               riscv_uart_tx;
  // In RTL-mask mode the BB stream belongs exclusively to the RTL endpoint.
  // Holding the soft-core RX idle prevents two endpoints from executing and
  // replying to the same mask command.
//`ifdef DEBUG_UART_DIRECT_CONNECT
  // Debug mode: bypass all routing logic, direct connection to SoC UART
  wire               riscv_uart_rx = DEBUG_UART_RX;
//`else
//  // Normal mode: use existing X2000 routing
//  wire               riscv_uart_rx = rtl_mask_mode ? 1'b1 : UART_ST_FR;
//`endif
  wire               riscv_system_reset;
  wire               riscv_memory_reset;
  wire [        3:0] riscv_gpio_write;
  wire [        3:0] riscv_gpio_write_enable;
  reg  [       15:0] riscv_uart_rx_count;
  reg  [       15:0] riscv_uart_tx_count;
  reg  [        1:0] riscv_uart_rx_sync;
  reg  [        1:0] riscv_uart_tx_sync;
  reg  [        1:0] machine_uart_tx_sync;
  reg  [        1:0] x2000_uart_tx_sync;
  reg  [       15:0] machine_uart_tx_count;
  reg  [       15:0] x2000_uart_tx_count;
  reg                 riscv_flash_cs_d;
  reg                 riscv_flash_clk_d;
  reg  [       15:0] riscv_flash_select_count;
  reg  [       31:0] riscv_flash_clock_count;
  wire [15:0]        riscv_diag_heartbeat;
  wire [7:0]         riscv_diag_boot_flags;
  wire [7:0]         riscv_diag_last_rx_byte;
  wire [15:0]        riscv_diag_rx_good_bytes;
  wire [15:0]        riscv_diag_rx_bad_frames;
  wire [7:0]         riscv_diag_last_error;
  wire [15:0]        riscv_diag_axi_errors;
  wire [31:0]        riscv_diag_rx_bytes;
  wire [31:0]        riscv_diag_tx_bytes;
  wire [31:0]        riscv_diag_last_axi_addr;
  wire [127:0]       riscv_diag_boot_read_data;
  wire [15:0]        riscv_diag_axi_write_addresses;
  wire [31:0]        riscv_diag_axi_write_beats;
  wire [15:0]        riscv_diag_axi_write_responses;
  wire [15:0]        riscv_diag_axi_read_addresses;
  wire [31:0]        riscv_diag_axi_read_beats;
  wire [15:0]        machine_good_frame_count;
  wire [15:0]        machine_bad_frame_count;
  wire [31:0]        machine_forwarded_bytes;
  // The bootloader copies the application from Flash into HyperRAM, so the
  // CPU must not leave reset before HyperRAM is usable.  Synchronize the
  // calibration result into the 50 MHz CPU domain and require it to remain
  // asserted for 5 ms before releasing Sapphire.  This makes cold boot use
  // the same deterministic sequence in debug and release builds.
  localparam [17:0] RISCV_BOOT_DELAY_CYCLES = 18'd250000; // 5 ms @ 50 MHz
  (* async_reg = "true" *) reg [1:0] riscv_hbc_cal_sync_50;
  reg  [17:0]        riscv_boot_delay_count;
  reg                riscv_boot_release;
  wire               riscv_hbc_cal_ready_50 = riscv_hbc_cal_sync_50[1];
  wire               riscv_diag_uart_rx = riscv_uart_monitor_x2000 ?
                                           riscv_uart_rx : UART_FPGA_TX;
  // hbc_cal_pass is used only to qualify the initial release.  Once the CPU
  // has started, do not gate its AXI port with the live calibration signal:
  // a short calibration-status glitch would otherwise interrupt the
  // bootloader copy and force the whole Flash-to-HyperRAM load to restart.
  wire               riscv_cpu_bus_enable = riscv_boot_release &
                                             uart_softcore_enable;
  wire               riscv_cpu_reset_active = ~riscv_boot_release |
                                                riscv_soft_reset_vio;

  always @(posedge clk50M or negedge sys_rst_n) begin
    if (!sys_rst_n)
      riscv_hbc_cal_sync_50 <= 2'b00;
    else
      riscv_hbc_cal_sync_50 <= {riscv_hbc_cal_sync_50[0],
                                hbc_cal_pass_synced};
  end

  always @(posedge clk50M or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      riscv_boot_delay_count <= 18'd0;
      riscv_boot_release     <= 1'b0;
    end else if (!riscv_boot_release) begin
      if (!riscv_hbc_cal_ready_50) begin
        riscv_boot_delay_count <= 18'd0;
      end else if (riscv_boot_delay_count == RISCV_BOOT_DELAY_CYCLES - 1'b1) begin
        riscv_boot_delay_count <= riscv_boot_delay_count;
        riscv_boot_release     <= 1'b1;
      end else begin
        riscv_boot_delay_count <= riscv_boot_delay_count + 1'b1;
      end
    end
  end

  // Isolate the disabled CPU cleanly from the shared arbiter.  These are the
  // arbiter-facing response wires; the CPU-facing wires below are gated.
  wire               cpu_arb_arw_ready, cpu_arb_w_ready;
  wire               cpu_arb_b_valid, cpu_arb_r_valid, cpu_arb_r_last;
  wire [7:0]         cpu_arb_b_id, cpu_arb_r_id;
  wire [AXI_DBW-1:0] cpu_arb_r_data;
  wire [1:0]         cpu_arb_r_resp;

  assign cpu_arw_ready = riscv_cpu_bus_enable ? cpu_arb_arw_ready : 1'b0;
  assign cpu_w_ready   = riscv_cpu_bus_enable ? cpu_arb_w_ready   : 1'b0;
  assign cpu_b_valid   = riscv_cpu_bus_enable ? cpu_arb_b_valid   : 1'b0;
  assign cpu_b_id      = cpu_arb_b_id;
  assign cpu_r_valid   = riscv_cpu_bus_enable ? cpu_arb_r_valid   : 1'b0;
  assign cpu_r_data    = cpu_arb_r_data;
  assign cpu_r_id      = cpu_arb_r_id;
  assign cpu_r_resp    = cpu_arb_r_resp;
  assign cpu_r_last    = cpu_arb_r_last;

  // Stage-3 video path: the known-good picture is first written to HyperRAM,
  // then read back and sent to ADV7391. The AXI readback checker drives the
  // existing test_good/test_fail VIO bits.
  wire [        7:0] picture_bt656_data;
  wire               picture_bt656_vsync;
  wire               picture_bt656_lsync;
  wire               adv7391_rstn_auto;
  wire               adv_init_busy;
  wire               adv_init_done;
  wire               adv_init_error;
  wire               adv_dbg_init_ok;
  wire               adv_dbg_sync_pins_ok;
  wire               adv_dbg_quiet_data_ok;
  wire               adv_dbg_xav_ok;
  wire               adv_dbg_line_cadence_ok;
  wire               adv_dbg_active_video_ok;
  wire               adv_dbg_field_ok;

  // BT.1120 -> 2x box filter -> fixed 9/8 bicubic scaler.
  wire [15:0] bt_dec_word;
  wire [7:0] bt_dec_y, bt_dec_c;
  wire [10:0] bt_dec_x, bt_dec_line;
  wire bt_dec_valid, bt_dec_sof, bt_dec_eof;
  wire bt_dec_sol, bt_dec_eol, bt_dec_frame_active;
  wire [7:0] prezoom_y, prezoom_c;
  wire prezoom_valid, prezoom_sof, prezoom_eof, prezoom_sol, prezoom_eol;
  wire prezoom_drop_epoch, prezoom_ready;
  wire [7:0] hot_stream_y, hot_stream_c;
  wire hot_stream_valid, hot_stream_sof, hot_stream_eof;
  wire hot_stream_sol, hot_stream_eol, hot_stream_drop_epoch;
  wire hot_stream_ready;
  wire [7:0] hot_cross_y_data, hot_cross_c_data;
  wire hot_cross_valid, hot_cross_sof, hot_cross_eof;
  wire hot_cross_sol, hot_cross_eol, hot_cross_drop_epoch;
  wire hot_cross_ready;
  wire [10:0] hot_result_x;
  wire [9:0] hot_result_y;
  wire [11:0] hot_result_sum;
  wire hot_result_valid;
  wire [15:0] hot_result_count, hot_dropped_result_count;
  wire [7:0] bt_ds_y, bt_ds_c;
  wire bt_ds_valid, bt_ds_sof, bt_ds_eol;
  wire bt_sync_locked, bt_protocol_error;
  wire [11:0] bt_error_info;
  wire [15:0] zoom_word;
  wire [7:0] zoom_y, zoom_c;
  wire [10:0] zoom_x, zoom_line;
  wire zoom_valid, zoom_sof, zoom_eof, zoom_sol, zoom_eol;
  wire zoom_output_ready;
  wire zoom_input_fifo_overflow;
  wire [15:0] zoom_captured_frames, zoom_output_frames, zoom_axi_errors;
  wire zoom_active;
  wire [10:0] zoom_active_left, zoom_active_top;
  wire [10:0] zoom_active_width, zoom_active_height;
  wire [63:0] zoom_capture_debug;
  wire [103:0] zoom_calculator_debug;
  wire [15:0] raster_pixel;
  wire [10:0] raster_x, raster_line;
  wire raster_valid, raster_sof, raster_eof, raster_sol, raster_eol;
  wire raster_input_ready, raster_frame_available;
  wire [15:0] raster_completed_frames, raster_displayed_frames;
  wire [15:0] raster_underflows, raster_axi_errors;
  wire [63:0] raster_writer_debug;
  wire [95:0] raster_reader_debug;
  wire [15:0] native_word;
  wire [7:0] native_y, native_c;
  wire [10:0] native_x, native_line;
  wire native_valid, native_sof, native_eof, native_sol, native_eol;
  wire bt_fifo_ready, bt_fifo_valid, bt_fifo_overflow;
  wire [17:0] bt_fifo_rdata;
  wire scaler_in_ready;
  wire [7:0] scaler_y, scaler_c;
  wire scaler_valid, scaler_sof, scaler_eol;
  wire scaler_fifo_ready, scaler_fifo_valid, scaler_fifo_overflow;
  wire [17:0] scaler_fifo_rdata;
  wire hram_pixel_ready;
  wire flip_input_ready, flip_output_valid;
  wire [15:0] flip_output_pixel;
  wire flip_output_sof, flip_output_eol;
// `ifdef ENABLE_VIO_DEBUG
//   wire cross_enable_vio;
//   wire [9:0] cross_x_vio, cross_y_vio;
// `endif
  wire scaler_frame_done, scaler_stream_error;
  wire [15:0] scaler_input_frame_count;
  wire [15:0] scaler_output_frame_count;
  wire [15:0] scaler_dropped_frame_count;
  wire [15:0] read_fifo_underflow_count;
  wire [15:0] frame_switch_count;
  wire [15:0] rejected_sof_count;
  wire [15:0] pal_frame_boundary_count;
  (* async_reg = "true" *) reg [15:0] scaler_input_count_meta, scaler_input_count_sync;
  (* async_reg = "true" *) reg [15:0] scaler_output_count_meta, scaler_output_count_sync;
  (* async_reg = "true" *) reg [15:0] scaler_drop_count_meta, scaler_drop_count_sync;
  (* async_reg = "true" *) reg [15:0] read_underflow_count_meta, read_underflow_count_sync;

  // Independent native-resolution DVP monitor path.  It serializes each
  // 16-bit BT.1120 word into two 8-bit DVP bytes and does not pass through
  // the scaler, HyperRAM frame buffer or ADV7391 path below.
  wire dvp_hsync_unused;
  wire dvp_clk_too_fast;
  wire dvp_fifo_overflow;
  // Protocol does not define the board-specific Y lane. VIO s2 bit 2 selects
  // high-byte Y when 1 and low-byte Y when 0. It does not affect PLL phase
  // unless the existing s0 manual phase override is also enabled.
  wire bt_y_from_high = dyn_pll_phase_sel[2];

  assign hbramClk_pll_rstn = 1'b1;
  assign sysClk_pll_rstn   = 1'b1;
  assign intosc_en         = 1'b1;
  assign DA_RST            = adv7391_rstn_auto;

  // Hold reset for 32768 clk cycles after PLL lock before releasing logic.
  always @(posedge clk or negedge hbramClk_pll_locked) begin
    if (!hbramClk_pll_locked) begin
      reset_cnt <= 16'd0;
    end else if (!reset_cnt[15]) begin
      reset_cnt <= reset_cnt + 16'd1;
    end
  end

  assign sys_rst_n           = hbramClk_pll_locked & reset_cnt[15];
  assign reset               = ~sys_rst_n;
  assign hbc_cal_pass_synced = hbc_cal_pass_sync;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      hbc_cal_pass_meta <= 1'b0;
      hbc_cal_pass_sync <= 1'b0;
      start             <= 2'b00;
    end else begin
      hbc_cal_pass_meta <= hbc_cal_pass;
      hbc_cal_pass_sync <= hbc_cal_pass_meta;
      start             <= {start[0], hbc_cal_pass_synced};
    end
  end

  // Count actual boot-Flash traffic in the RISC-V 50 MHz system domain.
  // These counters make a silent boot failure distinguishable from a missing
  // physical SPI connection without routing the high-rate SPI clock into VIO.
  always @(posedge clk50M or posedge riscv_cpu_reset_active) begin
    if (riscv_cpu_reset_active) begin
      riscv_flash_cs_d          <= 1'b1;
      riscv_flash_clk_d         <= 1'b0;
      riscv_flash_select_count  <= 16'd0;
      riscv_flash_clock_count   <= 32'd0;
    end else begin
      riscv_flash_cs_d  <= CFG_nCSO;
      riscv_flash_clk_d <= CFG_DCLK;
      if (riscv_flash_cs_d && !CFG_nCSO)
        riscv_flash_select_count <= riscv_flash_select_count + 1'b1;
      if (!CFG_nCSO && !riscv_flash_clk_d && CFG_DCLK)
        riscv_flash_clock_count <= riscv_flash_clock_count + 1'b1;
    end
  end

  // Diagnostic counters change only once per frame/event.  Two-stage sampling
  // makes them safe for the 100 MHz VIO clock domain.
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      scaler_input_count_meta <= 0; scaler_input_count_sync <= 0;
      scaler_output_count_meta <= 0; scaler_output_count_sync <= 0;
      scaler_drop_count_meta <= 0; scaler_drop_count_sync <= 0;
      read_underflow_count_meta <= 0; read_underflow_count_sync <= 0;
    end else begin
      scaler_input_count_meta <= scaler_input_frame_count;
      scaler_input_count_sync <= scaler_input_count_meta;
      scaler_output_count_meta <= scaler_output_frame_count;
      scaler_output_count_sync <= scaler_output_count_meta;
      scaler_drop_count_meta <= scaler_dropped_frame_count;
      scaler_drop_count_sync <= scaler_drop_count_meta;
      read_underflow_count_meta <= read_fifo_underflow_count;
      read_underflow_count_sync <= read_underflow_count_meta;
    end
  end

  RtlMaskUartAxiWriter #(
    .CLK_HZ(100000000), .BAUD(115200),
    .MASK_A_BASE(32'h00A0_0000), .MASK_B_BASE(32'h00B0_0000),
    .MASK_WIDTH(420), .MASK_HEIGHT(220)
  ) u_rtl_mask_uart_writer (
    .clk(clk), .reset(reset), .enable(rtl_mask_mode),
    // X2000 ttyS1 enters the bridge on UART_ST_FR. UART_FPGA_TX is the
    // opposite (machine-to-X2000) direction and must not feed this parser.
    .uart_rx(UART_ST_FR), .uart_tx(rtl_mask_uart_tx),
    .mask_enable(rtl_mask_enable), .active_buffer(rtl_mask_buffer),
    .mask_left(rtl_mask_left), .mask_top(rtl_mask_top),
    .avalid(rtl_a_valid), .aready(rtl_a_ready), .aaddr(rtl_a_addr),
    .aid(rtl_a_id), .alen(rtl_a_len), .asize(rtl_a_size),
    .aburst(rtl_a_burst), .alock(rtl_a_lock), .atype(rtl_a_write),
    .wvalid(rtl_w_valid), .wready(rtl_w_ready), .wid(rtl_w_id),
    .wdata(rtl_w_data), .wstrb(rtl_w_strb), .wlast(rtl_w_last),
    .bvalid(rtl_b_valid), .bready(rtl_b_ready), .bid(rtl_b_id),
    .good_packet_count(rtl_good_packets), .bad_packet_count(rtl_bad_packets),
    .received_bytes(rtl_received_bytes), .axi_error_count(rtl_axi_errors),
    .writer_active(rtl_writer_active)
  );

  // Machine-command forwarder.  X2000 sends all commands on UART_ST_FR:
  // 0xAA machine frames are validated and re-serialized to UART_FPGA_RX,
  // while 0xBB mask frames stay with the mask endpoint above.
  UartMachineForwarder #(
    .CLK_HZ(100000000), .BAUD(115200)
  ) u_uart_machine_forwarder (
    .clk(clk), .reset(reset),
    .uart_rx(UART_ST_FR),
    .machine_tx(UART_FPGA_RX),
    .good_frame_count(machine_good_frame_count),
    .bad_frame_count(machine_bad_frame_count),
    .forwarded_bytes(machine_forwarded_bytes)
  );

  // Flat memory-client map, slot 0 at the least-significant end:
  //   0 final video DMA, 1 mask reader, 2 UART mask writer,
  //   3 zoom source/calculator, 4 zoom raster buffer, 5 RISC-V CPU.
  // New memory users get a peer slot here instead of another arbiter layer.
  assign mem_a_valid = {cpu_arw_valid & riscv_cpu_bus_enable,
                        zr_a_valid, ze_a_valid, rtl_a_valid,
                        mask_rd_arw_valid, vid_arw_valid};
  assign mem_a_addr  = {cpu_arw_addr, zr_a_addr, ze_a_addr, rtl_a_addr,
                        mask_rd_arw_addr, vid_arw_addr};
  assign mem_a_id    = {cpu_arw_id, zr_a_id, ze_a_id, rtl_a_id,
                        mask_rd_arw_id, vid_arw_id};
  assign mem_a_len   = {cpu_arw_len, zr_a_len, ze_a_len, rtl_a_len,
                        mask_rd_arw_len, vid_arw_len};
  assign mem_a_size  = {cpu_arw_size, zr_a_size, ze_a_size, rtl_a_size,
                        mask_rd_arw_size, vid_arw_size};
  assign mem_a_burst = {cpu_arw_burst, zr_a_burst, ze_a_burst, rtl_a_burst,
                        mask_rd_arw_burst, vid_arw_burst};
  assign mem_a_lock  = {{1'b0,cpu_arw_lock}, zr_a_lock, ze_a_lock,
                        rtl_a_lock, mask_rd_arw_lock, vid_arw_lock};
  assign mem_a_write = {cpu_arw_write, zr_a_write, ze_a_write, rtl_a_write,
                        mask_rd_arw_write, vid_arw_write};

  assign {cpu_arb_arw_ready, zr_a_ready, ze_a_ready, rtl_a_ready,
          mask_rd_arw_ready, vid_arw_ready} = mem_a_ready;

  assign mem_w_valid = {cpu_w_valid & riscv_cpu_bus_enable,
                        zr_w_valid, ze_w_valid, rtl_w_valid,
                        1'b0, vid_w_valid};
  assign mem_w_data  = {cpu_w_data, zr_w_data, ze_w_data, rtl_w_data,
                        {AXI_DBW{1'b0}}, vid_w_data};
  assign mem_w_strb  = {cpu_w_strb, zr_w_strb, ze_w_strb, rtl_w_strb,
                        {AXI_SBW{1'b0}}, vid_w_strb};
  assign mem_w_last  = {cpu_w_last, zr_w_last, ze_w_last, rtl_w_last,
                        1'b0, vid_w_last};
  assign {cpu_arb_w_ready, zr_w_ready, ze_w_ready, rtl_w_ready,
          mem_unused_mask_w_ready, vid_w_ready} = mem_w_ready;

  assign mem_b_ready = {cpu_b_ready & riscv_cpu_bus_enable,
                        zr_b_ready, ze_b_ready, rtl_b_ready,
                        1'b1, vid_b_ready};
  assign {cpu_arb_b_valid, zr_b_valid, ze_b_valid, rtl_b_valid,
          mem_unused_mask_b_valid, vid_b_valid} = mem_b_valid;
  assign {cpu_arb_b_id, zr_b_id, ze_b_id, rtl_b_id,
          mem_unused_mask_b_id, vid_b_id} = mem_b_id;

  assign mem_r_ready = {cpu_r_ready & riscv_cpu_bus_enable,
                        zr_r_ready, ze_r_ready, 1'b1,
                        mask_rd_r_ready, vid_r_ready};
  assign {cpu_arb_r_valid, zr_r_valid, ze_r_valid, mem_unused_rtl_r_valid,
          mask_rd_r_valid, vid_r_valid} = mem_r_valid;
  assign {cpu_arb_r_data, zr_r_data, ze_r_data, mem_unused_rtl_r_data,
          mask_rd_r_data, vid_r_data} = mem_r_data;
  assign {cpu_arb_r_id, zr_r_id, ze_r_id, mem_unused_rtl_r_id,
          mask_rd_r_id, vid_r_id} = mem_r_id;
  assign {cpu_arb_r_resp, zr_r_resp, ze_r_resp, mem_unused_rtl_r_resp,
          mask_rd_r_resp, vid_r_resp} = mem_r_resp;
  assign {cpu_arb_r_last, zr_r_last, ze_r_last, mem_unused_rtl_r_last,
          mask_rd_r_last, vid_r_last} = mem_r_last;

  AxiSharedFlatFabric #(
    .PORTS(MEM_PORTS), .DATA_WIDTH(AXI_DBW), .STRB_WIDTH(AXI_SBW),
    .ID_WIDTH(8),
    // Slot order (MSB -> LSB): cpu, zr, ze, rtl, mask_rd, vid.  Preserve the
    // former weighted service: video 2, zoom source/raster 4, all others 1.
    .WEIGHTS({8'd1, 8'd4, 8'd4, 8'd1, 8'd1, 8'd2})
  ) u_hyperram_axi_fabric (
    .clk(clk), .reset(reset),
    .m_a_valid(mem_a_valid), .m_a_ready(mem_a_ready),
    .m_a_addr(mem_a_addr), .m_a_id(mem_a_id), .m_a_len(mem_a_len),
    .m_a_size(mem_a_size), .m_a_burst(mem_a_burst),
    .m_a_lock(mem_a_lock), .m_a_write(mem_a_write),
    .m_w_valid(mem_w_valid), .m_w_ready(mem_w_ready),
    .m_w_data(mem_w_data), .m_w_strb(mem_w_strb), .m_w_last(mem_w_last),
    .m_b_valid(mem_b_valid), .m_b_ready(mem_b_ready), .m_b_id(mem_b_id),
    .m_r_valid(mem_r_valid), .m_r_ready(mem_r_ready),
    .m_r_data(mem_r_data), .m_r_id(mem_r_id),
    .m_r_resp(mem_r_resp), .m_r_last(mem_r_last),
    .s_a_valid(io_arw_valid), .s_a_ready(io_arw_ready),
    .s_a_addr(io_arw_payload_addr), .s_a_id(io_arw_payload_id),
    .s_a_len(io_arw_payload_len), .s_a_size(io_arw_payload_size),
    .s_a_burst(io_arw_payload_burst), .s_a_lock(io_arw_payload_lock),
    .s_a_write(io_arw_payload_write),
    .s_w_valid(io_w_valid), .s_w_ready(io_w_ready),
    .s_w_data(io_w_payload_data), .s_w_strb(io_w_payload_strb),
    .s_w_last(io_w_payload_last), .s_w_id(io_w_payload_id),
    .s_b_valid(io_b_valid), .s_b_ready(io_b_ready), .s_b_id(io_b_payload_id),
    .s_r_valid(io_r_valid), .s_r_ready(io_r_ready),
    .s_r_data(io_r_payload_data), .s_r_id(io_r_payload_id),
    .s_r_resp(io_r_payload_resp), .s_r_last(io_r_payload_last)
  );

  assign zoom_a_valid = ze_a_valid | zr_a_valid;
  assign zoom_a_ready = ze_a_valid ? ze_a_ready : zr_a_ready;
  assign zoom_a_write = ze_a_valid ? ze_a_write : zr_a_write;
  assign zoom_w_valid = ze_w_valid | zr_w_valid;
  assign zoom_w_ready = ze_w_valid ? ze_w_ready : zr_w_ready;
  assign zoom_w_last  = ze_w_valid ? ze_w_last : zr_w_last;
  assign zoom_b_valid = ze_b_valid | zr_b_valid;
  assign zoom_b_ready = ze_b_valid ? ze_b_ready : zr_b_ready;
  assign zoom_r_valid = ze_r_valid | zr_r_valid;
  assign zoom_r_ready = ze_r_valid ? ze_r_ready : zr_r_ready;
  assign zoom_r_last  = ze_r_valid ? ze_r_last : zr_r_last;
  assign zoom_r_resp  = ze_r_valid ? ze_r_resp : zr_r_resp;

`ifdef HYPERRAM_DUAL
  dual_hyperram_ctrl hbram_top_inst (
    .rst                 (reset),
    .ram_clk             (hbramClk),
    .ram_clk_cal         (hbramClk_cal),
    .ram_clk_cal_2       (hbramClk_cal_2),
    .io_axi_clk          (clk),
    .io_arw_valid        (io_arw_valid),
    .io_arw_ready        (io_arw_ready),
    .io_arw_payload_addr (io_arw_payload_addr),
    .io_arw_payload_id   (io_arw_payload_id),
    .io_arw_payload_len  (io_arw_payload_len),
    .io_arw_payload_size (io_arw_payload_size),
    .io_arw_payload_burst(io_arw_payload_burst),
    .io_arw_payload_lock (io_arw_payload_lock),
    .io_arw_payload_write(io_arw_payload_write),
    .io_w_payload_id     (io_w_payload_id),
    .io_w_valid          (io_w_valid),
    .io_w_ready          (io_w_ready),
    .io_w_payload_data   (io_w_payload_data),
    .io_w_payload_strb   (io_w_payload_strb),
    .io_w_payload_last   (io_w_payload_last),
    .io_b_valid          (io_b_valid),
    .io_b_ready          (io_b_ready),
    .io_b_payload_id     (io_b_payload_id),
    .io_r_valid          (io_r_valid),
    .io_r_ready          (io_r_ready),
    .io_r_payload_data   (io_r_payload_data),
    .io_r_payload_id     (io_r_payload_id),
    .io_r_payload_resp   (io_r_payload_resp),
    .io_r_payload_last   (io_r_payload_last),
    .dyn_pll_phase_en    (dyn_pll_phase_en),
    .dyn_pll_phase_sel   (dyn_pll_phase_sel),
    .hbc_cal_SHIFT_ENA   (hbc_cal_SHIFT_ENA_int),
    .hbc_cal_SHIFT       (hbc_cal_SHIFT_int),
    .hbc_cal_SHIFT_SEL   (hbc_cal_SHIFT_SEL),
    .hbc_cal_pass        (hbc_cal_pass),
    .hbc_cal_debug_info  (hbc_cal_debug_info),
    .hbc_rst_n           (hbc_rst_n),
    .hbc_cs_n            (hbc_cs_n),
    .hbc_ck_p_HI         (hbc_ck_p_HI),
    .hbc_ck_p_LO         (hbc_ck_p_LO),
    .hbc_ck_n_HI         (hbc_ck_n_HI),
    .hbc_ck_n_LO         (hbc_ck_n_LO),
    .hbc_rwds_OUT_HI     (hbc_rwds_OUT_HI),
    .hbc_rwds_OUT_LO     (hbc_rwds_OUT_LO),
    .hbc_rwds_IN_HI      (hbc_rwds_IN_HI),
    .hbc_rwds_IN_LO      (hbc_rwds_IN_LO),
    .hbc_rwds_OE         (hbc_rwds_OE),
    .hbc_dq_OUT_HI       (hbc_dq_OUT_HI),
    .hbc_dq_OUT_LO       (hbc_dq_OUT_LO),
    .hbc_dq_IN_HI        (hbc_dq_IN_HI),
    .hbc_dq_IN_LO        (hbc_dq_IN_LO),
    .hbc_dq_OE           (hbc_dq_OE),
    .hbc_rst_n_2         (hbc_rst_n_2),
    .hbc_cs_n_2          (hbc_cs_n_2),
    .hbc_ck_p_HI_2       (hbc_ck_p_2_HI),
    .hbc_ck_p_LO_2       (hbc_ck_p_2_LO),
    .hbc_ck_n_HI_2       (hbc_ck_n_2_HI),
    .hbc_ck_n_LO_2       (hbc_ck_n_2_LO),
    .hbc_rwds_OUT_HI_2   (hbc_rwds_2_OUT_HI),
    .hbc_rwds_OUT_LO_2   (hbc_rwds_2_OUT_LO),
    .hbc_rwds_IN_HI_2    (hbc_rwds_2_IN_HI),
    .hbc_rwds_IN_LO_2    (hbc_rwds_2_IN_LO),
    .hbc_rwds_OE_2       (hbc_rwds_2_OE),
    .hbc_dq_OUT_HI_2     (hbc_dq_2_OUT_HI),
    .hbc_dq_OUT_LO_2     (hbc_dq_2_OUT_LO),
    .hbc_dq_IN_HI_2      (hbc_dq_2_IN_HI),
    .hbc_dq_IN_LO_2      (hbc_dq_2_IN_LO),
    .hbc_dq_OE_2         (hbc_dq_2_OE)
  );
`else
  hyperram_ctrl hbram_top_inst (
    .rst                 (reset),
    .ram_clk             (hbramClk),
    .ram_clk_cal         (hbramClk_cal),
    .io_axi_clk          (clk),
    .io_arw_valid        (io_arw_valid),
    .io_arw_ready        (io_arw_ready),
    .io_arw_payload_addr (io_arw_payload_addr),
    .io_arw_payload_id   (io_arw_payload_id),
    .io_arw_payload_len  (io_arw_payload_len),
    .io_arw_payload_size (io_arw_payload_size),
    .io_arw_payload_burst(io_arw_payload_burst),
    .io_arw_payload_lock (io_arw_payload_lock),
    .io_arw_payload_write(io_arw_payload_write),
    .io_w_payload_id     (io_w_payload_id),
    .io_w_valid          (io_w_valid),
    .io_w_ready          (io_w_ready),
    .io_w_payload_data   (io_w_payload_data),
    .io_w_payload_strb   (io_w_payload_strb),
    .io_w_payload_last   (io_w_payload_last),
    .io_b_valid          (io_b_valid),
    .io_b_ready          (io_b_ready),
    .io_b_payload_id     (io_b_payload_id),
    .io_r_valid          (io_r_valid),
    .io_r_ready          (io_r_ready),
    .io_r_payload_data   (io_r_payload_data),
    .io_r_payload_id     (io_r_payload_id),
    .io_r_payload_resp   (io_r_payload_resp),
    .io_r_payload_last   (io_r_payload_last),
    .dyn_pll_phase_en    (dyn_pll_phase_en),
    .dyn_pll_phase_sel   (dyn_pll_phase_sel),
    .hbc_cal_SHIFT_ENA   (hbc_cal_SHIFT_ENA_int),
    .hbc_cal_SHIFT       (hbc_cal_SHIFT_int),
    .hbc_cal_SHIFT_SEL   (hbc_cal_SHIFT_SEL),
    .hbc_cal_pass        (hbc_cal_pass),
    .hbc_cal_debug_info  (hbc_cal_debug_info),
    .hbc_rst_n           (hbc_rst_n),
    .hbc_cs_n            (hbc_cs_n),
    .hbc_ck_p_HI         (hbc_ck_p_HI),
    .hbc_ck_p_LO         (hbc_ck_p_LO),
    .hbc_ck_n_HI         (hbc_ck_n_HI),
    .hbc_ck_n_LO         (hbc_ck_n_LO),
    .hbc_rwds_OUT_HI     (hbc_rwds_OUT_HI),
    .hbc_rwds_OUT_LO     (hbc_rwds_OUT_LO),
    .hbc_rwds_IN_HI      (hbc_rwds_IN_HI),
    .hbc_rwds_IN_LO      (hbc_rwds_IN_LO),
    .hbc_rwds_OE         (hbc_rwds_OE),
    .hbc_dq_OUT_HI       (hbc_dq_OUT_HI),
    .hbc_dq_OUT_LO       (hbc_dq_OUT_LO),
    .hbc_dq_IN_HI        (hbc_dq_IN_HI),
    .hbc_dq_IN_LO        (hbc_dq_IN_LO),
    .hbc_dq_OE           (hbc_dq_OE)
  );
`endif

  // Decode embedded BT.1120 timing exactly once.  Both output branches consume
  // this canonical active-pixel stream, so SAV/EAV state cannot diverge.
  Bt1120Decoder #(
    .FRAME_WIDTH(1280), .FRAME_HEIGHT(1024)
  ) u_bt1120_decoder (
    .clk            (bt1120_clk),
    .reset          ((~sys_rst_n) | (~pll_bt1120_locked)),
    .bt_data        (bt1120_data),
    .y_from_high    (bt_y_from_high),
    .pixel_word     (bt_dec_word),
    .pixel_y        (bt_dec_y),
    .pixel_c        (bt_dec_c),
    .pixel_x        (bt_dec_x),
    .pixel_line     (bt_dec_line),
    .pixel_valid    (bt_dec_valid),
    .pixel_sof      (bt_dec_sof),
    .pixel_eof      (bt_dec_eof),
    .pixel_sol      (bt_dec_sol),
    .pixel_eol      (bt_dec_eol),
    .frame_active   (bt_dec_frame_active),
    .sync_locked    (bt_sync_locked),
    .protocol_error (bt_protocol_error),
    .error_info     (bt_error_info)
  );

  ConfigSnapshotCdc #(.WIDTH(45)) u_zoom_config_cdc (
    .src_clk(clk50M), .src_reset(riscv_cpu_reset_active),
    .src_data({zoom_cfg_enable_axi, zoom_cfg_left_axi, zoom_cfg_top_axi,
               zoom_cfg_width_axi, zoom_cfg_height_axi}),
    .src_toggle(zoom_cfg_toggle_axi), .src_ack_toggle(zoom_cfg_ack_axi),
    .dst_clk(clk), .dst_reset(reset), .dst_data(zoom_cfg_video),
    .dst_pending(zoom_cfg_pending), .dst_apply(zoom_cfg_apply),
    .dst_apply_pulse(zoom_cfg_apply_pulse)
  );

  assign zoom_enable_command     = zoom_cfg_video[44];
  assign zoom_roi_left_command   = zoom_cfg_video[43:33];
  assign zoom_roi_top_command    = zoom_cfg_video[32:22];
  assign zoom_roi_width_command  = zoom_cfg_video[21:11];
  assign zoom_roi_height_command = zoom_cfg_video[10:0];

  // ElectronicZoomFrameBuffer publishes its active geometry only at the
  // safe boundary it actually consumed.  Match against those active outputs
  // before returning the AXI-domain acknowledgement.
  assign zoom_cfg_apply = zoom_cfg_pending &&
      ((!zoom_enable_command && !zoom_active) ||
       (zoom_enable_command && zoom_active &&
        (zoom_active_left == zoom_roi_left_command) &&
        (zoom_active_top == zoom_roi_top_command) &&
        (zoom_active_width == zoom_roi_width_command) &&
        (zoom_active_height == zoom_roi_height_command)));

  ConfigSnapshotCdc #(.WIDTH(2)) u_mask_config_cdc (
    .src_clk(clk50M), .src_reset(riscv_cpu_reset_active),
    .src_data({mask_cfg_enable_axi, mask_cfg_buffer_axi}),
    .src_toggle(mask_cfg_toggle_axi), .src_ack_toggle(mask_cfg_ack_axi),
    .dst_clk(clk), .dst_reset(reset), .dst_data(mask_cfg_video),
    .dst_pending(mask_cfg_pending), .dst_apply(mask_cfg_apply),
    .dst_apply_pulse(mask_cfg_apply_pulse)
  );

  ConfigSnapshotCdc #(.WIDTH(2)) u_hot_config_cdc (
    .src_clk(clk50M), .src_reset(riscv_cpu_reset_active),
    .src_data({hot_cfg_enable_axi, hot_cfg_black_hot_axi}),
    .src_toggle(hot_cfg_toggle_axi), .src_ack_toggle(hot_cfg_ack_axi),
    .dst_clk(clk), .dst_reset(reset), .dst_data(hot_cfg_video),
    .dst_pending(hot_cfg_pending), .dst_apply(hot_cfg_apply),
    .dst_apply_pulse(hot_cfg_apply_pulse)
  );

  // Hot-focus controls become active on the same accepted pre-zoom SOF used
  // by the tracker and crosshair.
  assign hot_cfg_apply = hot_cfg_pending && prezoom_valid && prezoom_sof &&
                         prezoom_ready;

  // The existing overlay contains two synchronizer stages on these controls.
  // Wait three clk cycles after receipt, then acknowledge only when its SOF
  // pixel is accepted.  This guarantees STATUS.pending never clears before
  // the new canvas selection can have become frame-active.
  always @(posedge clk or posedge reset) begin
    if (reset || !mask_cfg_pending)
      mask_cfg_settle <= 2'd0;
    else if (mask_cfg_settle != 2'd3)
      mask_cfg_settle <= mask_cfg_settle + 1'b1;
  end
  assign mask_cfg_apply = mask_cfg_pending && (mask_cfg_settle == 2'd3) &&
                          flip_output_valid && flip_output_sof &&
                          mask_input_ready;

  // Publish one coherent result packet whenever a complete result is added,
  // a damaged frame is counted, or validity changes.  The tracker holds the
  // packet stable for a whole video frame, giving the request/acknowledge CDC
  // ample time to capture it atomically in clk50M.
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      hot_result_toggle <= 1'b0;
      hot_result_count_seen <= 0;
      hot_dropped_count_seen <= 0;
      hot_result_valid_seen <= 1'b0;
    end else if ((hot_result_count != hot_result_count_seen) ||
                 (hot_dropped_result_count != hot_dropped_count_seen) ||
                 (hot_result_valid != hot_result_valid_seen)) begin
      hot_result_toggle <= ~hot_result_toggle;
      hot_result_count_seen <= hot_result_count;
      hot_dropped_count_seen <= hot_dropped_result_count;
      hot_result_valid_seen <= hot_result_valid;
    end
  end

  ConfigSnapshotCdc #(.WIDTH(66)) u_hot_result_cdc (
    .src_clk(clk), .src_reset(reset),
    .src_data({hot_result_x, hot_result_y, hot_result_sum, hot_result_valid,
               hot_result_count, hot_dropped_result_count}),
    .src_toggle(hot_result_toggle),
    .src_ack_toggle(hot_result_ack_toggle),
    .dst_clk(clk50M), .dst_reset(riscv_cpu_reset_active),
    .dst_data(hot_result_snapshot_axi),
    .dst_pending(hot_result_snapshot_pending),
    .dst_apply(hot_result_snapshot_pending),
    .dst_apply_pulse(hot_result_snapshot_apply_pulse)
  );

  assign {hot_result_x_axi, hot_result_y_axi, hot_result_sum_axi,
          hot_result_valid_axi, hot_result_count_axi,
          hot_dropped_count_axi} = hot_result_snapshot_axi;

  PreZoomVideoIngress u_prezoom_ingress (
    .input_clk(bt1120_clk),
    .input_reset((~sys_rst_n) | (~pll_bt1120_locked)),
    .input_y(bt_dec_y), .input_c(bt_dec_c), .input_valid(bt_dec_valid),
    .input_sof(bt_dec_sof), .input_eof(bt_dec_eof),
    .input_sol(bt_dec_sol), .input_eol(bt_dec_eol),
    .clk(clk), .reset(reset),
    .output_y(prezoom_y), .output_c(prezoom_c),
    .output_valid(prezoom_valid), .output_sof(prezoom_sof),
    .output_eof(prezoom_eof), .output_sol(prezoom_sol),
    .output_eol(prezoom_eol), .output_drop_epoch(prezoom_drop_epoch),
    .output_ready(prezoom_ready),
    .fifo_overflow(zoom_input_fifo_overflow)
  );

  wire [10:0] hot_roi_right = zoom_enable_command ?
      (zoom_roi_left_command + zoom_roi_width_command - 1'b1) : 11'd1279;
  wire [9:0] hot_roi_bottom = zoom_enable_command ?
      (zoom_roi_top_command[9:0] + zoom_roi_height_command[9:0] - 1'b1) :
      10'd1023;

  HotFocusCal u_hot_focus_cal (
    .clk(clk), .reset(reset),
    .s_y(prezoom_y), .s_c(prezoom_c), .s_valid(prezoom_valid),
    .s_sof(prezoom_sof), .s_eof(prezoom_eof),
    .s_sol(prezoom_sol), .s_eol(prezoom_eol),
    .s_drop_epoch(prezoom_drop_epoch), .s_ready(prezoom_ready),
    .m_y(hot_stream_y), .m_c(hot_stream_c),
    .m_valid(hot_stream_valid), .m_sof(hot_stream_sof),
    .m_eof(hot_stream_eof), .m_sol(hot_stream_sol),
    .m_eol(hot_stream_eol), .m_drop_epoch(hot_stream_drop_epoch),
    .m_ready(hot_stream_ready),
    .enable(hot_cfg_video[1]),
    .polarity_black_hot(hot_cfg_video[0]),
    .roi_left(zoom_enable_command ? zoom_roi_left_command : 11'd0),
    .roi_right(hot_roi_right),
    .roi_top(zoom_enable_command ? zoom_roi_top_command[9:0] : 10'd0),
    .roi_bottom(hot_roi_bottom),
    .hot_x(hot_result_x), .hot_y(hot_result_y),
    .hot_sum(hot_result_sum), .hot_valid(hot_result_valid),
    .result_count(hot_result_count),
    .dropped_result_count(hot_dropped_result_count)
  );

  HotFocusCrosshairYuv422 u_hot_focus_crosshair (
    .clk(clk), .reset(reset),
    .s_y(hot_stream_y), .s_c(hot_stream_c),
    .s_valid(hot_stream_valid), .s_sof(hot_stream_sof),
    .s_eof(hot_stream_eof), .s_sol(hot_stream_sol),
    .s_eol(hot_stream_eol), .s_drop_epoch(hot_stream_drop_epoch),
    .s_ready(hot_stream_ready),
    .m_y(hot_cross_y_data), .m_c(hot_cross_c_data),
    .m_valid(hot_cross_valid), .m_sof(hot_cross_sof),
    .m_eof(hot_cross_eof), .m_sol(hot_cross_sol),
    .m_eol(hot_cross_eol), .m_drop_epoch(hot_cross_drop_epoch),
    .m_ready(hot_cross_ready),
    .cross_enable(hot_cfg_video[1] && hot_result_valid),
    .cross_x(hot_result_x), .cross_y(hot_result_y)
  );

  // Native frame store and arbitrary ROI bicubic zoom.  Both a full-frame 1x
  // command and a zoomed ROI traverse this same source/scaler/raster path;
  // the committed 1280x1024 raster is shared by both downstream branches.
  ElectronicZoomFrameBuffer #(
    .FRAME_A_BASE(32'h0100_0000), .FRAME_B_BASE(32'h0128_0000),
    .FRAME_C_BASE(32'h0150_0000), .EXTERNAL_INPUT(1)
  ) u_electronic_zoom (
    .input_clk(clk), .input_reset(reset),
    .input_y(hot_cross_y_data), .input_c(hot_cross_c_data),
    .input_valid(hot_cross_valid),
    .input_sof(hot_cross_sof), .input_eof(hot_cross_eof),
    .input_sol(hot_cross_sol), .input_eol(hot_cross_eol),
    .input_drop_epoch(hot_cross_drop_epoch), .input_ready(hot_cross_ready),
    .clk(clk), .reset(reset), .y_from_high(bt_y_from_high),
    .zoom_enable_command(zoom_enable_command),
    .roi_left_command(zoom_roi_left_command),
    .roi_top_command(zoom_roi_top_command),
    .roi_width_command(zoom_roi_width_command),
    .roi_height_command(zoom_roi_height_command),
    .output_word(zoom_word), .output_y(zoom_y), .output_c(zoom_c),
    .output_x(zoom_x), .output_line(zoom_line),
    .output_valid(zoom_valid), .output_sof(zoom_sof),
    .output_eof(zoom_eof), .output_sol(zoom_sol), .output_eol(zoom_eol),
    .output_ready(zoom_output_ready),
    .avalid(ze_a_valid), .aready(ze_a_ready), .aaddr(ze_a_addr),
    .aid(ze_a_id), .alen(ze_a_len), .asize(ze_a_size),
    .aburst(ze_a_burst), .alock(ze_a_lock), .atype(ze_a_write),
    .wvalid(ze_w_valid), .wready(ze_w_ready), .wid(ze_w_id),
    .wdata(ze_w_data), .wstrb(ze_w_strb), .wlast(ze_w_last),
    .bvalid(ze_b_valid), .bready(ze_b_ready), .bid(ze_b_id),
    .rvalid(ze_r_valid), .rready(ze_r_ready), .rdata(ze_r_data),
    .rid(ze_r_id), .rresp(ze_r_resp), .rlast(ze_r_last),
    .input_fifo_overflow(),
    .captured_frame_count(zoom_captured_frames),
    .zoom_output_frame_count(zoom_output_frames),
    .axi_error_count(zoom_axi_errors), .active_zoom(zoom_active),
    .active_left(zoom_active_left), .active_top(zoom_active_top),
    .active_width(zoom_active_width), .active_height(zoom_active_height),
    .debug_capture_state(zoom_capture_debug),
    .debug_calculator_state(zoom_calculator_debug)
  );

  // Commit sparse calculator results to a second three-buffer HyperRAM store,
  // then regenerate a continuous native raster.  The output triple buffer
  // deliberately does not overlap the source-frame triple buffer at
  // 0x01000000/0x01280000/0x01500000.
  assign zoom_output_ready = raster_input_ready;
  ElectronicZoomRasterBuffer #(
    .FRAME_A_BASE(32'h0180_0000), .FRAME_B_BASE(32'h01A8_0000),
    .FRAME_C_BASE(32'h01D0_0000)
  ) u_electronic_zoom_raster (
    .clk(clk), .reset(reset), .enable(1'b1),
    .input_pixel({zoom_c,zoom_y}),
    .input_valid(zoom_valid),
    .input_sof(zoom_sof), .input_eof(zoom_eof),
    .input_ready(raster_input_ready),
    .output_pixel(raster_pixel), .output_x(raster_x),
    .output_line(raster_line), .output_valid(raster_valid),
    .output_sof(raster_sof), .output_eof(raster_eof),
    .output_sol(raster_sol), .output_eol(raster_eol),
    .avalid(zr_a_valid), .aready(zr_a_ready), .aaddr(zr_a_addr),
    .aid(zr_a_id), .alen(zr_a_len), .asize(zr_a_size),
    .aburst(zr_a_burst), .alock(zr_a_lock), .atype(zr_a_write),
    .wvalid(zr_w_valid), .wready(zr_w_ready), .wid(zr_w_id),
    .wdata(zr_w_data), .wstrb(zr_w_strb), .wlast(zr_w_last),
    .bvalid(zr_b_valid), .bready(zr_b_ready), .bid(zr_b_id),
    .rvalid(zr_r_valid), .rready(zr_r_ready), .rdata(zr_r_data),
    .rid(zr_r_id), .rresp(zr_r_resp), .rlast(zr_r_last),
    .frame_available(raster_frame_available),
    .completed_frame_count(raster_completed_frames),
    .displayed_frame_count(raster_displayed_frames),
    .output_underflow_count(raster_underflows),
    .axi_error_count(raster_axi_errors),
    .debug_writer_state(raster_writer_debug),
    .debug_reader_state(raster_reader_debug)
  );

  // Both 1x and zoomed operation use the same committed raster stream.  A
  // disabled zoom command is translated to the full 1280x1024 ROI inside the
  // calculator, so there is no raw/raster datapath switch at top level.
  assign native_y     = raster_pixel[7:0];
  assign native_c     = raster_pixel[15:8];
  assign native_x     = raster_x;
  assign native_line  = raster_line;
  assign native_valid = raster_valid;
  assign native_sof   = raster_sof;
  assign native_eof   = raster_eof;
  assign native_sol   = raster_sol;
  assign native_eol   = raster_eol;
  assign native_word  = bt_y_from_high ? {native_y,native_c} : {native_c,native_y};

  // Native-resolution branch: format the post-zoom stream as 8-bit DVP.
  DvpFormatter u_dvp_formatter (
    .input_clk        (clk),
    .input_reset      (~sys_rst_n),
    .input_word       (native_word),
    .input_valid      (native_valid),
    .input_sof        (native_sof),
    .input_eof        (native_eof),
    .input_sol        (native_sol),
    .input_eol        (native_eol),
    .dvp_clk          (clk_dvp),
    .dvp_reset        ((~sys_rst_n) | (~pll_bt1120_locked)),
    .dvp_vsync        (dvp_vs),
    .dvp_hsync        (dvp_hsync_unused),
    .dvp_valid        (dvp_hs),
    .dvp_data         (dvp_data),
    .dvp_clk_too_fast (dvp_clk_too_fast),
    .fifo_overflow    (dvp_fifo_overflow)
  );

  // CVBS branch stage 1: consume the same post-zoom native stream.
  Downsample2xYuv422 u_downsample_2x (
    .clk       (clk),
    .reset     (~sys_rst_n),
    .in_y      (native_y),
    .in_c      (native_c),
    .in_x      (native_x),
    .in_line   (native_line),
    .in_valid  (native_valid),
    .out_y     (bt_ds_y),
    .out_c     (bt_ds_c),
    .out_valid (bt_ds_valid),
    .out_sof   (bt_ds_sof),
    .out_eol   (bt_ds_eol)
  );

  // AA machine replies and BB soft-core replies share the X2000 RX wire.
  // The removed 0xCC RTL zoom parser has no third UART reply path.
  wire mask_reply_tx = rtl_mask_mode ? rtl_mask_uart_tx :
                       riscv_uart_reply_enable ? riscv_uart_tx : 1'b1;
//`ifdef DEBUG_UART_DIRECT_CONNECT
  // Debug mode: direct SoC UART TX to dedicated debug pin
 // assign DEBUG_UART_TX = riscv_uart_tx;

  assign DEBUG_UART_TX =  riscv_gpio_write[0];

//  assign DEBUG_UART_TX = 1;

  assign UART_SR_FT = UART_FPGA_TX & mask_reply_tx;  // Keep X2000 path unchanged
//`else
//  // Normal mode: SoC UART TX goes to X2000
//  assign UART_SR_FT = UART_FPGA_TX & mask_reply_tx;
//  assign DEBUG_UART_TX = 1'b1;  // Idle state when not in debug mode
//`endif
// `ifdef ENABLE_VIO_DEBUG
//   wire mask_vio_override = riscv_manual_mode_vio;
// `else
  wire mask_vio_override = 1'b0;
// `endif
  // Normal operation uses the AXI snapshot.  VIO and the pure-RTL writer are
  // retained only as explicit commissioning fallbacks until board validation.
  assign mask_enable = rtl_mask_mode ? rtl_mask_enable :
                       mask_vio_override ? mask_enable_vio :
                       mask_cfg_video[1];
  assign mask_buffer_select = rtl_mask_mode ? rtl_mask_buffer :
                              mask_vio_override ? mask_buffer_select_vio :
                              mask_cfg_video[0];

  // Count UART start edges for board-level bring-up.  These counters prove
  // pin activity; firmware-controlled GPIO below is the execution proof.
  always @(posedge clk50M or negedge sys_rst_n) begin
    if (!sys_rst_n) begin
      riscv_uart_rx_sync  <= 2'b11;
      riscv_uart_tx_sync  <= 2'b11;
      machine_uart_tx_sync <= 2'b11;
      x2000_uart_tx_sync   <= 2'b11;
      riscv_uart_rx_count <= 16'd0;
      riscv_uart_tx_count <= 16'd0;
      machine_uart_tx_count <= 16'd0;
      x2000_uart_tx_count   <= 16'd0;
    end else begin
      riscv_uart_rx_sync <= {riscv_uart_rx_sync[0], UART_FPGA_TX};
      riscv_uart_tx_sync <= {riscv_uart_tx_sync[0], riscv_uart_tx};
      machine_uart_tx_sync <= {machine_uart_tx_sync[0], UART_FPGA_RX};
      x2000_uart_tx_sync <= {x2000_uart_tx_sync[0], UART_SR_FT};
      if (riscv_uart_rx_sync == 2'b10)
        riscv_uart_rx_count <= riscv_uart_rx_count + 1'b1;
      if (riscv_uart_tx_sync == 2'b10)
        riscv_uart_tx_count <= riscv_uart_tx_count + 1'b1;
      if (machine_uart_tx_sync == 2'b10)
        machine_uart_tx_count <= machine_uart_tx_count + 1'b1;
      if (x2000_uart_tx_sync == 2'b10)
        x2000_uart_tx_count <= x2000_uart_tx_count + 1'b1;
    end
  end

  // Dedicated activity counter for the actual X2000-to-FPGA mask RX side.
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      rtl_uart_rx_sync <= 2'b11;
      rtl_uart_rx_edge_count <= 16'd0;
    end else begin
      rtl_uart_rx_sync <= {rtl_uart_rx_sync[0], UART_ST_FR};
      if (rtl_uart_rx_sync == 2'b10)
        rtl_uart_rx_edge_count <= rtl_uart_rx_edge_count + 1'b1;
    end
  end

  // Minimal Sapphire instance.  The 4 KiB on-chip boot RAM remains active,
  // while DDR/HyperRAM and AXI-A inputs are held inactive until the arbiter
  // integration step.  This prevents the new core from disturbing video.
  RiscvVioMonitor #(
    .CLK_HZ(100000000),
    .UART_BAUD(115200)
  ) u_riscv_vio_monitor (
    .clk              (clk),
    .reset            (reset),
    .clear            (riscv_diag_clear),
    .hbc_cal_pass     (hbc_cal_pass_synced),
    .cpu_enable       (riscv_cpu_bus_enable),
    .cpu_reset        (riscv_cpu_reset_active | riscv_system_reset |
                       riscv_memory_reset),
    .gpio_activity    (|(riscv_gpio_write_enable & riscv_gpio_write)),
    .uart_rx          (riscv_diag_uart_rx),
    .uart_tx          (riscv_uart_tx),
    .axi_arw_valid    (cpu_arw_valid),
    .axi_arw_ready    (cpu_arw_ready),
    .axi_arw_write    (cpu_arw_write),
    .axi_arw_addr     (cpu_arw_addr),
    .axi_w_valid      (cpu_w_valid),
    .axi_w_ready      (cpu_w_ready),
    .axi_b_valid      (cpu_b_valid),
    .axi_b_ready      (cpu_b_ready),
    .axi_b_resp       (2'b00),
    .axi_r_valid      (cpu_r_valid),
    .axi_r_ready      (cpu_r_ready),
    .axi_r_data       (cpu_r_data),
    .axi_r_resp       (cpu_r_resp),
    .heartbeat        (riscv_diag_heartbeat),
    .boot_flags       (riscv_diag_boot_flags),
    .last_rx_byte     (riscv_diag_last_rx_byte),
    .rx_good_bytes    (riscv_diag_rx_good_bytes),
    .rx_bad_frames    (riscv_diag_rx_bad_frames),
    .last_error       (riscv_diag_last_error),
    .axi_errors       (riscv_diag_axi_errors),
    .rx_bytes         (riscv_diag_rx_bytes),
    .tx_bytes         (riscv_diag_tx_bytes),
    .last_axi_addr    (riscv_diag_last_axi_addr),
    .boot_read_data   (riscv_diag_boot_read_data),
    .axi_write_addresses(riscv_diag_axi_write_addresses),
    .axi_write_beats  (riscv_diag_axi_write_beats),
    .axi_write_responses(riscv_diag_axi_write_responses),
    .axi_read_addresses(riscv_diag_axi_read_addresses),
    .axi_read_beats   (riscv_diag_axi_read_beats)
  );

  Ti60AxiControlFabric #(.BUILD_ID(32'h0000_0001))
  u_ti60_axi_control (
    .clk(clk50M), .reset(riscv_cpu_reset_active),
    .s_awvalid(axia_awvalid), .s_awready(axia_awready),
    .s_awaddr(axia_awaddr), .s_awid(axia_awid), .s_awlen(axia_awlen),
    .s_awsize(axia_awsize), .s_awburst(axia_awburst),
    .s_awlock(axia_awlock), .s_awcache(axia_awcache),
    .s_awprot(axia_awprot), .s_awqos(axia_awqos),
    .s_wvalid(axia_wvalid), .s_wready(axia_wready),
    .s_wdata(axia_wdata), .s_wstrb(axia_wstrb), .s_wlast(axia_wlast),
    .s_bvalid(axia_bvalid), .s_bready(axia_bready),
    .s_bid(axia_bid), .s_bresp(axia_bresp),
    .s_arvalid(axia_arvalid), .s_arready(axia_arready),
    .s_araddr(axia_araddr), .s_arid(axia_arid), .s_arlen(axia_arlen),
    .s_arsize(axia_arsize), .s_arburst(axia_arburst),
    .s_arlock(axia_arlock), .s_arcache(axia_arcache),
    .s_arprot(axia_arprot), .s_arqos(axia_arqos),
    .s_rvalid(axia_rvalid), .s_rready(axia_rready),
    .s_rdata(axia_rdata), .s_rid(axia_rid),
    .s_rresp(axia_rresp), .s_rlast(axia_rlast),
    .zoom_cfg_enable(zoom_cfg_enable_axi),
    .zoom_cfg_left(zoom_cfg_left_axi), .zoom_cfg_top(zoom_cfg_top_axi),
    .zoom_cfg_width(zoom_cfg_width_axi),
    .zoom_cfg_height(zoom_cfg_height_axi),
    .zoom_cfg_toggle(zoom_cfg_toggle_axi),
    .zoom_applied_toggle(zoom_cfg_ack_axi),
    .zoom_accepted_count(zoom_accepted_count),
    .zoom_rejected_count(zoom_rejected_count),
    .mask_cfg_enable(mask_cfg_enable_axi),
    .mask_cfg_buffer_select(mask_cfg_buffer_axi),
    .mask_cfg_toggle(mask_cfg_toggle_axi),
    .mask_applied_toggle(mask_cfg_ack_axi),
    .mask_commit_count(mask_commit_count),
    .hot_cfg_enable(hot_cfg_enable_axi),
    .hot_cfg_black_hot(hot_cfg_black_hot_axi),
    .hot_cfg_toggle(hot_cfg_toggle_axi),
    .hot_applied_toggle(hot_cfg_ack_axi),
    .hot_result_x(hot_result_x_axi), .hot_result_y(hot_result_y_axi),
    .hot_result_sum(hot_result_sum_axi),
    .hot_result_valid(hot_result_valid_axi),
    .hot_result_count(hot_result_count_axi),
    .hot_dropped_result_count(hot_dropped_count_axi),
    .hot_commit_count(hot_commit_count)
  );

  riscv u_riscv (
    .io_systemClk                    (clk50M),
    .io_asyncReset                   (riscv_cpu_reset_active),
    .io_memoryClk                    (clk),
    .io_systemReset                  (riscv_system_reset),
    .io_memoryReset                  (riscv_memory_reset),
    .system_uart_0_io_txd            (riscv_uart_tx),
    .system_uart_0_io_rxd            (riscv_uart_rx),
    .system_gpio_0_io_write          (riscv_gpio_write),
    .system_gpio_0_io_writeEnable    (riscv_gpio_write_enable),
    .system_gpio_0_io_read           (4'b0000),

    .jtagCtrl_enable                 (jtag_inst1_SEL),
    .jtagCtrl_tdi                    (jtag_inst1_TDI),
    .jtagCtrl_tdo                    (jtag_inst1_TDO),
    .jtagCtrl_capture                (jtag_inst1_CAPTURE),
    .jtagCtrl_shift                  (jtag_inst1_SHIFT),
    .jtagCtrl_update                 (jtag_inst1_UPDATE),
    .jtagCtrl_reset                  (jtag_inst1_RESET),
    .jtagCtrl_tck                    (jtag_inst1_TCK),  

    .axiA_awvalid                    (axia_awvalid),
    .axiA_awready                    (axia_awready),
    .axiA_awaddr                     (axia_awaddr),
    .axiA_awid                       (axia_awid),
    .axiA_awlen                      (axia_awlen),
    .axiA_awsize                     (axia_awsize),
    .axiA_awburst                    (axia_awburst),
    .axiA_awlock                     (axia_awlock),
    .axiA_awcache                    (axia_awcache),
    .axiA_awqos                      (axia_awqos),
    .axiA_awprot                     (axia_awprot),
    .axiA_wvalid                     (axia_wvalid),
    .axiA_wready                     (axia_wready),
    .axiA_wdata                      (axia_wdata),
    .axiA_wstrb                      (axia_wstrb),
    .axiA_wlast                      (axia_wlast),
    .axiA_bvalid                     (axia_bvalid),
    .axiA_bready                     (axia_bready),
    .axiA_bid                        (axia_bid),
    .axiA_bresp                      (axia_bresp),
    .axiA_arvalid                    (axia_arvalid),
    .axiA_arready                    (axia_arready),
    .axiA_araddr                     (axia_araddr),
    .axiA_arid                       (axia_arid),
    .axiA_arlen                      (axia_arlen),
    .axiA_arsize                     (axia_arsize),
    .axiA_arburst                    (axia_arburst),
    .axiA_arlock                     (axia_arlock),
    .axiA_arcache                    (axia_arcache),
    .axiA_arqos                      (axia_arqos),
    .axiA_arprot                     (axia_arprot),
    .axiA_rvalid                     (axia_rvalid),
    .axiA_rready                     (axia_rready),
    .axiA_rdata                      (axia_rdata),
    .axiA_rid                        (axia_rid),
    .axiA_rresp                      (axia_rresp),
    .axiA_rlast                      (axia_rlast),
    .axiAInterrupt                   (1'b0),

    .io_ddrA_arw_ready               (cpu_arw_ready),
    .io_ddrA_w_ready                 (cpu_w_ready),
    .io_ddrA_b_valid                 (cpu_b_valid),
    .io_ddrA_b_payload_id            (cpu_b_id),
    .io_ddrA_b_payload_resp          (2'b00),
    .io_ddrA_r_valid                 (cpu_r_valid),
    .io_ddrA_r_payload_data          (cpu_r_data),
    .io_ddrA_r_payload_id            (cpu_r_id),
    .io_ddrA_r_payload_resp          (cpu_r_resp),
    .io_ddrA_r_payload_last          (cpu_r_last),
    .io_ddrA_arw_valid               (cpu_arw_valid),
    .io_ddrA_arw_payload_addr        (cpu_arw_addr),
    .io_ddrA_arw_payload_id          (cpu_arw_id),
    .io_ddrA_arw_payload_region      (),
    .io_ddrA_arw_payload_len         (cpu_arw_len),
    .io_ddrA_arw_payload_size        (cpu_arw_size),
    .io_ddrA_arw_payload_burst       (cpu_arw_burst),
    .io_ddrA_arw_payload_lock        (cpu_arw_lock),
    .io_ddrA_arw_payload_cache       (),
    .io_ddrA_arw_payload_qos         (),
    .io_ddrA_arw_payload_prot        (),
    .io_ddrA_arw_payload_write       (cpu_arw_write),
    .io_ddrA_w_valid                 (cpu_w_valid),
    .io_ddrA_w_payload_data          (cpu_w_data),
    .io_ddrA_w_payload_strb          (cpu_w_strb),
    .io_ddrA_w_payload_id            (cpu_w_id),
    .io_ddrA_w_payload_last          (cpu_w_last),
    .io_ddrA_b_ready                 (cpu_b_ready),
    .io_ddrA_r_ready                 (cpu_r_ready),

    .system_spi_0_io_ss              (CFG_nCSO),
    .system_spi_0_io_sclk_write      (CFG_DCLK),
    .system_spi_0_io_data_0_read     (CFG_D0_IN),
    .system_spi_0_io_data_0_write    (CFG_D0_OUT),
    .system_spi_0_io_data_0_writeEnable(CFG_D0_OE),
    .system_spi_0_io_data_1_read     (CFG_D1_IN),
    .system_spi_0_io_data_1_write    (CFG_D1_OUT),
    .system_spi_0_io_data_1_writeEnable(CFG_D1_OE),
    .system_spi_0_io_data_2_read     (CFG_D2_IN),
    .system_spi_0_io_data_2_write    (CFG_D2_OUT),
    .system_spi_0_io_data_2_writeEnable(CFG_D2_OE),
    .system_spi_0_io_data_3_read     (CFG_D3_IN),
    .system_spi_0_io_data_3_write    (CFG_D3_OUT),
    .system_spi_0_io_data_3_writeEnable(CFG_D3_OE),
    .system_i2c_0_io_scl_read        (1'b1),
    .system_i2c_0_io_sda_read        (1'b1)

  );


  // CVBS branch stage 2: cross from the BT.1120 clock domain to scaler clock.
  VideoAsyncFifo #(.WIDTH(18), .ADDR_W(11)) u_bt_video_fifo (
    .wr_clk(clk), .wr_reset(~sys_rst_n),
    .wr_data({bt_ds_sof, bt_ds_eol, bt_ds_c, bt_ds_y}),
    .wr_valid(bt_ds_valid), .wr_ready(bt_fifo_ready),
    .overflow(bt_fifo_overflow),
    .rd_clk(clk_scaler), .rd_reset((~sys_rst_n) | (~pll_bt1120_locked)),
    .rd_data(bt_fifo_rdata), .rd_valid(bt_fifo_valid),
    .rd_ready(scaler_in_ready)
  );

  // CVBS branch stage 3: fixed-ratio bicubic scaling, 640x512 -> 720x576.
  BicubicScaler640x512 u_bicubic_scaler (
    .clk(clk_scaler), .reset((~sys_rst_n) | (~pll_bt1120_locked)),
    .in_y(bt_fifo_rdata[7:0]), .in_c(bt_fifo_rdata[15:8]),
    .in_valid(bt_fifo_valid), .in_sof(bt_fifo_rdata[17]),
    .in_eol(bt_fifo_rdata[16]), .in_ready(scaler_in_ready),
    .out_y(scaler_y), .out_c(scaler_c), .out_valid(scaler_valid),
    .out_sof(scaler_sof), .out_eol(scaler_eol),
    .out_ready(scaler_fifo_ready), .frame_done(scaler_frame_done),
    .stream_error(scaler_stream_error),
    .input_frame_count(scaler_input_frame_count),
    .output_frame_count(scaler_output_frame_count),
    .dropped_frame_count(scaler_dropped_frame_count)
  );

  // CVBS branch stage 4: return the scaled stream to the HyperRAM AXI domain.
  VideoAsyncFifo #(.WIDTH(18), .ADDR_W(11)) u_scaler_to_axi_fifo (
    .wr_clk(clk_scaler), .wr_reset((~sys_rst_n) | (~pll_bt1120_locked)),
    .wr_data({scaler_sof, scaler_eol, scaler_c, scaler_y}),
    .wr_valid(scaler_valid), .wr_ready(scaler_fifo_ready),
    .overflow(scaler_fifo_overflow),
    .rd_clk(clk), .rd_reset(~sys_rst_n),
    .rd_data(scaler_fifo_rdata), .rd_valid(scaler_fifo_valid),
    .rd_ready(flip_input_ready)
  );

  // CVBS branch stage 5: horizontal rotation component; preserve YUV422 parity.
  VideoHorizontalFlipYuv422 #(
    .FRAME_WIDTH(720), .FRAME_HEIGHT(576)
  ) u_video_horizontal_flip (
    .clk(clk), .reset(~sys_rst_n),
    .s_data(scaler_fifo_rdata[15:0]), .s_valid(scaler_fifo_valid),
    .s_sof(scaler_fifo_rdata[17]), .s_eol(scaler_fifo_rdata[16]),
    .s_ready(flip_input_ready),
    .m_data(flip_output_pixel), .m_valid(flip_output_valid),
    .m_sof(flip_output_sof), .m_eol(flip_output_eol),
    .m_ready(mask_input_ready)
  );

  // Soft-core software writes a complete 8-bit mask canvas to 0x0040_0000.
  // The image-generation command performs placement and edge clipping; this
  // block only consumes the resulting full-screen canvas in pixel order.
  HyperRamMaskOverlayYuv422 #(
    .MASK0_BASE(32'h0040_0000),
    .MASK1_BASE(32'h0050_0000),
    .RTL_MASK0_BASE(32'h00A0_0000),
    .RTL_MASK1_BASE(32'h00B0_0000),
    .FRAME_WIDTH(720), .FRAME_HEIGHT(576),
    .RAW_MASK_WIDTH(420), .RAW_MASK_HEIGHT(220),
    .FLIP_VERTICAL_COORDS(1)
  ) u_hyperram_mask_overlay (
    .clk(clk), .reset(reset), .mask_enable(mask_enable),
    .mask_buffer_select(mask_buffer_select),
    .raw_mode(rtl_mask_mode),
    .mask_left(rtl_mask_left), .mask_top(rtl_mask_top),
    .s_data(flip_output_pixel), .s_valid(flip_output_valid),
    .s_sof(flip_output_sof), .s_eol(flip_output_eol),
